\label{Thm:main}

There exists a
$\kappa_r$-tuple $(\epsilon_i)_{i=1}^{\kappa_r}\in \{ \pm 1 \}^{\kappa_r}$, 
 unique up to sign, 
  such that 
for any $y\in Y_r$ and for a suitable choice of the branch of the hyperlogarithm $AI_i^{r-2}$ at $y_i=U_i(y)\in \mathbf P^1$ for each $i=1,\ldots,\kappa_r$, the following functional identity 
holds true  on an open neighbourhood of $y$ in $ Y_r$: 
$$ {}^{} \hspace{-6cm}
\boldsymbol{\big({\bf H Log}(X_r)\big) }
\hspace{3.7cm}
\sum_{i=1}^{\kappa_r} \epsilon_i \,AI_i^{r-2}\big(U_i\big)=0\, .
$$

\label{Prop:Symbolic}

For $(c_i)_{i=1}^d \in \mathbf C^d$, the following conditions are equivalent: 

\begin{enumerate}

\item[1.]  one has $\sum_{i=1}^d c_i\,\Omega_i=0$ in $\wedge^s H\subset H^{\otimes s}$;
\smallskip

\item[2.] there exists $y\in Y$, such that $\sum_{i=1}^d c_i\,{AI}^s_{i,y_i}(U_i)=0$ as a holomorphic germ at $y$ on $Y$;
\smallskip

\item[3.] for any $y\in Y$, one has $\sum_{i=1}^d c_i\,{AI}^s_{i,y_i}(U_i)=0$ as a holomorphic germ at $y$ on $Y$.

\smallskip


\end{enumerate}

\label{Prop:Key}


 For $r=4,5,6,7,8$, one has the following decompositions of\, $\mathbf C^{{\mathcal L}_r}$ in irreducible $W_r$-modules: 

\begin{align}
\label{Eq:Decomposition-Wr}

\mathbf C^{{\mathcal L}_4}=& \, {\bf 1}\oplus V_{[41]}^4\oplus V_{[32]}^5 \nonumber \\

\mathbf C^{{\mathcal L}_5}=&  \, 
{\bf 1}\oplus V_{[4,1]}^5\oplus V_{[3,2]}^{10} 

 \nonumber   \\

\mathbf C^{{\mathcal L}_6}=&  
\, {\bf 1}\oplus V^{6,1}\oplus V^{20,2} 


\\

\mathbf C^{{\mathcal L}_7}=&   \, 
{\bf 1} \oplus V^{7,1}\oplus V^{21,3}\oplus V^{27,2}





\nonumber 

\\

\mathbf C^{{\mathcal L}_8}=&   \,  
{\bf 1} \oplus V^{8,1} 
\oplus V^{35,2} 
\oplus V^{84,4} 
\oplus V^{112,3} \, .
\medskip


 \nonumber 
 \smallskip

\end{align}

\label{L:basis-varpi-c}

The tuple $\big(\varpi_{\mathfrak c}\big)_{ \mathfrak c \in {\mathcal K}_r}$ 
is well defined (up to sign) and forms a basis of $\oplus_{\mathfrak c \in {\mathcal K}_r}  \wedge^{r-2}  
\mathcal U_{\mathfrak c}$.

\label{L:Psi-r-2-equiv}

{\rm 1.} The map $\Psi^{r-2}$  is $W_r$-equivariant.\smallskip

{\rm 2.} As $W_r$-modules, one has $\bigoplus_{\mathfrak c \in {\mathcal K}_r}  \wedge^{r-2}  
\mathcal U_{\mathfrak c}\simeq \boldsymbol{\epsilon}\otimes \mathbf C^{{\mathcal K}_r}$.

\label{Fact-mult-signature}
For $r=4,\ldots,8$, let $m^{\boldsymbol{\epsilon}}_r$ 
be the multiplicity of the signature representation in the decomposition 
of $\wedge ^{r-2} \mathbf C^{ {\mathcal L}_r}$ into $W_r$-irreducibles.  Then 






\begin{equation}
\label{m-signa}
m^{\boldsymbol{\epsilon}}_r=
\begin{cases} 
\, 0 \hspace{0.3cm} \mbox{for } \, r=4,\ldots,7 \\
\, 5 \hspace{0.3cm} \mbox{for } \, r=8\, .
\end{cases}
\end{equation}

{\it Bol's web is characterized by $r_{ \boldsymbol{\mathcal B}}$: 
any 5-web $\boldsymbol{\mathcal W}$ such that $r_{ \boldsymbol{\mathcal W},3}\equiv 1$
and $r_{ \boldsymbol{\mathcal W},5}\leq 5$ is equivalent to Bol's web.}

{\it The class of 27-webs $\boldsymbol{\mathcal W}_{{\rm dP}_3}$'s is characterized by $r_{\boldsymbol{\mathcal W}_{{\rm dP}_3},3}$: any 27-web 
$\boldsymbol{\mathcal W}$ such that $r_{ \boldsymbol{\mathcal W},3}\sim r_{\boldsymbol{\mathcal W}_{{\rm dP}_3},3}$
 is equivalent to  the 27-web in conics on a cubic surface in $\mathbf P^3$.}
